// Define a capability interface
public interface IMyData {
    int getValue();
    void setValue(int value);
}

// Create the capability
public static final Capability<IMyData> MY_DATA_CAPABILITY = CapabilityManager.get(new ResourceLocation(MODID, "my_data"));

// Implement ICapabilityProvider
public class MyDataProvider implements ICapabilityProvider, IForgeCapabilitySerializable<CompoundNBT> {
    private IMyData data = new IMyData() {
        private int value;
        @Override public int getValue() { return value; }
        @Override public void setValue(int v) { value = v; }
    };

    @Override
    public <T> LazyOptional<T> getCapability(Capability<T> cap, Direction side) {
        return MY_DATA_CAPABILITY.orEmpty(cap, LazyOptional.of(() -> data));
    }

    @Override
    public CompoundNBT serializeNBT() { return NBTUtils.intToTag(data.getValue()); }
    @Override
    public void deserializeNBT(CompoundNBT nbt) { data.setValue(NBTUtils.tagToInt(nbt)); }
}
